	/**
	 * Provides static methods for the computation of intersections, projections, sections and similar.
	 */
	class Intersection {
		/**
		 * Intersects two arcs using exact calculations.
		 * @param arcA First arc to intersect.
		 * @param arcB Second arc to intersect.
		 * @returns The intersection type.
		 */
		static arcArc(arcA: Arc, arcB: Arc): [ArcArcIntersection, Point3d, Point3d];
		/**
		 * Intersects two circles using exact calculations.
		 * @param circleA First circle to intersect.
		 * @param circleB Second circle to intersect.
		 * @returns The intersection type.
		 */
		static circleCircle(circleA: Circle, circleB: Circle): [CircleCircleIntersection, Point3d, Point3d];
		/**
		 * Intersects an infinite line and an axis aligned bounding box.
		 * @param line Line for intersection.
		 * @param box BoundingBox to intersect.
		 * @param tolerance If tolerance > 0.0, then the intersection is performed against a box that has each side moved out by tolerance.
		 * @returns true if the line intersects the box, false if no intersection occurs.
		 */
		static lineBox(line: Line, box: BoundingBox, tolerance: number): [boolean, Interval];
		/**
		 * Intersects an infinite line and an axis aligned bounding box.
		 * @param line Line for intersection.
		 * @param box BoundingBox to intersect.
		 * @param tolerance If tolerance > 0.0, then the intersection is performed against a box that has each side moved out by tolerance.
		 * @returns true if the line intersects the box, false if no intersection occurs.
		 */
		static lineBox(line: Line, box: Box, tolerance: number): [boolean, Interval];
		/**
		 * Intersects a line with a circle using exact calculations.
		 * @param line Line for intersection.
		 * @param circle Circle for intersection.
		 * @returns If `LineCircleIntersection.Single` is returned, only t1 and point1 will have valid values. If `LineCircleIntersection.Multiple` is returned, t2 and point2 will also be filled out.
		 */
		static lineCircle(line: Line, circle: Circle): [LineCircleIntersection, number, Point3d, number, Point3d];
		/**
		 * Intersects a line with a cylinder using exact calculations.
		 * @param line Line for intersection.
		 * @param cylinder Cylinder for intersection.
		 * @returns If None is returned, the first point is the point on the line closest to the cylinder and the second point is the point on the cylinder closest to the line. If `LineCylinderIntersection.Single` is returned, the first point is the point on the line and the second point is the same point on the cylinder.
		 */
		static lineCylinder(line: Line, cylinder: Cylinder): [LineCylinderIntersection, Point3d, Point3d];
		/**
		 * Find the unique closest-points pair between two infinite lines, if it exists.
		 * @param lineA First line.
		 * @param lineB Second line.
		 * @returns true if points are found and false if the lines are numerically parallel. Numerically parallel means the 2x2 matrix: +AoA -AoB -AoB +BoB is numerically singular, where A = (lineA.To - lineA.From) and B = (lineB.To-lineB.From).
		 */
		static lineLine(lineA: Line, lineB: Line): [boolean, number, number];
		/**
		 * Intersects two lines.
		 *
		 * If the lines are exactly parallel, meaning the system of equations used to find a and b has no numerical solution, then false is returned. If the lines are nearly parallel, which is often numerically true even if you think the lines look exactly parallel, then the closest points are found and true is returned. So, if you care about weeding out "parallel" lines, then you need to do something like the following: `bool rc = Intersect.LineLine(lineA, lineB, out a, out b, tolerance, segments); if (rc) { double angle_tol = RhinoMath.ToRadians(1.0); // or whatever double parallel_tol = Math.Cos(angle_tol); if ( Math.Abs(lineA.UnitTangent * lineB.UnitTangent) >= parallel_tol ) { ... do whatever you think is appropriate } }` `Dim rc As Boolean = Intersect.LineLine(lineA, lineB, a, b, tolerance, segments) If (rc) Then Dim angle_tol As Double = RhinoMath.ToRadians(1.0) 'or whatever Dim parallel_tolerance As Double = Math.Cos(angle_tol) If (Math.Abs(lineA.UnitTangent * lineB.UnitTangent) >= parallel_tolerance) Then ... do whatever you think is appropriate End If End If`
		 * @param lineA First line for intersection.
		 * @param lineB Second line for intersection.
		 * @param tolerance If tolerance > 0.0, then an intersection is reported only if the distance between the points is <= tolerance. If tolerance <= 0.0, then the closest point between the lines is reported.
		 * @param finiteSegments If true, the input lines are treated as finite segments. If false, the input lines are treated as infinite lines.
		 * @returns true if a closest point can be calculated and the result passes the tolerance parameter test; otherwise false.
		 */
		static lineLine(lineA: Line, lineB: Line, tolerance: number, finiteSegments: boolean): [boolean, number, number];
		/**
		 * Intersects a line and a plane. This function only returns true if the intersection result is a single point (i.e. if the line is coincident with the plane then no intersection is assumed).
		 * @param line Line for intersection.
		 * @param plane Plane to intersect.
		 * @returns true on success, false on failure.
		 */
		static linePlane(line: Line, plane: Plane): [boolean, number];
		/**
		 * Intersects a line with a sphere using exact calculations.
		 * @param line Line for intersection.
		 * @param sphere Sphere for intersection.
		 * @returns If `LineSphereIntersection.None` is returned, the first point is the point on the line closest to the sphere and the second point is the point on the sphere closest to the line. If `LineSphereIntersection.Single` is returned, the first point is the point on the line and the second point is the same point on the sphere.
		 */
		static lineSphere(line: Line, sphere: Sphere): [LineSphereIntersection, Point3d, Point3d];
		/**
		 * Intersects a plane with a circle using exact calculations.
		 * @param plane Plane to intersect.
		 * @param circle Circe to intersect.
		 * @returns The type of intersection that occurred.
		 */
		static planeCircle(plane: Plane, circle: Circle): [PlaneCircleIntersection, number, number];
		/**
		 * Intersects two planes and return the intersection line. If the planes are parallel or coincident, no intersection is assumed.
		 * @param planeA First plane for intersection.
		 * @param planeB Second plane for intersection.
		 * @returns true on success, false on failure.
		 */
		static planePlane(planeA: Plane, planeB: Plane): [boolean, Line];
		/**
		 * Intersects three planes to find the single point they all share.
		 * @param planeA First plane for intersection.
		 * @param planeB Second plane for intersection.
		 * @param planeC Third plane for intersection.
		 * @returns true on success, false on failure. If at least two out of the three planes are parallel or coincident, failure is assumed.
		 */
		static planePlanePlane(planeA: Plane, planeB: Plane, planeC: Plane): [boolean, Point3d];
		/**
		 * Intersects a plane with a sphere using exact calculations.
		 * @param plane Plane to intersect.
		 * @param sphere Sphere to intersect.
		 * @returns If `PlaneSphereIntersection.None` is returned, the intersectionCircle has a radius of zero and the center point is the point on the plane closest to the sphere.
		 */
		static planeSphere(plane: Plane, sphere: Sphere): [PlaneSphereIntersection, Circle];
		/**
		 * Intersects two spheres using exact calculations.
		 * @param sphereA First sphere to intersect.
		 * @param sphereB Second sphere to intersect.
		 * @returns The intersection type.
		 */
		static sphereSphere(sphereA: Sphere, sphereB: Sphere): [SphereSphereIntersection, Circle];
	}

