	/**
	 * Maintains an index to every model component that is in the 3dm file. This is the "more comprehensive" table that contains all objects in all other tables.
	 */
	class ManifestTable {
		/**
		 * Total number of items in the manifest, including deleted items.
		 */
		activeObjectCount(type: ModelComponentType): number;
		/**
		 * Returns `ModelComponentType.Mixed`.
		 */
		readonly componentType: ModelComponentType;
		/**
		 * Total number of items in the manifest, including deleted items.
		 */
		readonly count: number;
		/**
		 * Uses the guid to find a model component. Deleted objects cannot be found by id. The guid is the value that is stored in the .Id property. In a single document, no two active objects have the same guid. If an object is replaced with a new object, then the guid persists. For example, if the _Move command moves an object, then the moved object inherits its guid from the starting object. If the Copy command copies an object, then the copy gets a new guid. This guid persists through file saving/opening operations. This function will not find grip objects.
		 * @param id ID of model component to search for.
		 * @param type The type to be searched. If this is `ModelComponentType.Unset` then all types are searched.
		 * @returns Reference to the rhino object with the objectId or null if no such object could be found.
		 */
		findId(id: string, type: ModelComponentType): ModelComponent;
		/**
		 * Uses the guid to find a model component. Deleted objects cannot be found by id. The guid is the value that is stored in the .Id property. In a single document, no two active objects have the same guid. If an object is replaced with a new object, then the guid persists. For example, if the _Move command moves an object, then the moved object inherits its guid from the starting object. If the Copy command copies an object, then the copy gets a new guid. This guid persists through file saving/opening operations. This function will not find grip objects.
		 * @param id ID of model component to search for.
		 * @returns Reference to the rhino object with the objectId or null if no such object could be found.
		 */
		findId(id: string): ModelComponent;
		/**
		 * Uses the index to find a model component. The index is the value that is stored in the .Index property.
		 * @param index Index of model component to search for.
		 * @param type The type to be searched. Cannot be `ModelComponentType.Unset`.
		 * @returns Reference to the rhino object or null if no such object could be found.
		 */
		findIndex(index: number, type: ModelComponentType): ModelComponent;
		/**
		 * Uses the name to find a model component. The name is the value that is stored in the .Name property. Deleted objects have no name.
		 * @param name Name of model component to search for.
		 * @param type The type to be searched. Cannot be `ModelComponentType.Unset`.
		 * @returns Reference to the rhino object or null if no such object could be found.
		 */
		findName(name: string, type: ModelComponentType, parentId: any): ModelComponent;
		/**
		 * Returns an enumerators that yields all model components, including default ones, relating to a particular type.
		 * @param type The model component type.
		 * @returns An enumerator.
		 */
		getEnumerator(type: ModelComponentType): ManifestTableIter;
		/** An iterator over the items (`for...of` works on the object itself). */
		iterator(): ManifestTableIter;
		/**
		 * Total number of items in the manifest, including deleted items.
		 */
		readonly longCount: number;
		/** Iterates the items: `for (const x of manifestTable)`. */
		[Symbol.iterator](): Iterator<ModelComponent>;
	}

	class ManifestTableIter {
		/** The next item: `{done: true}` at the end. */
		next(): { done: boolean, value?: ModelComponent };
		/** Iterates the items: `for (const x of manifestTableIter)`. */
		[Symbol.iterator](): Iterator<ModelComponent>;
	}

